import { useState } from 'react';
import {
  Segmented,
  SegmentedItem,
  Slider,
  Switch,
  Select,
  SelectItem,
  Divider,
  Badge,
  Text,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettingsValue {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

interface AppearanceSettingsProps {
  defaultValue?: Partial<AppearanceSettingsValue>;
  onChange?: (value: AppearanceSettingsValue) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_LABELS: Record<FontFamily, string> = {
  system: 'Системный',
  inter: 'Inter',
  mono: 'Моно',
};

export default function AppearanceSettings({
  defaultValue,
  onChange,
}: AppearanceSettingsProps) {
  const [theme, setTheme] = useState<Theme>(defaultValue?.theme ?? 'system');
  const [scale, setScale] = useState<number>(defaultValue?.scale ?? 100);
  const [dense, setDense] = useState<boolean>(defaultValue?.dense ?? false);
  const [font, setFont] = useState<FontFamily>(defaultValue?.font ?? 'system');

  const emit = (next: Partial<AppearanceSettingsValue>) => {
    onChange?.({
      theme: next.theme ?? theme,
      scale: next.scale ?? scale,
      dense: next.dense ?? dense,
      font: next.font ?? font,
    });
  };

  const handleThemeChange = (next: Theme) => {
    setTheme(next);
    emit({ theme: next });
  };

  const handleScaleChange = (next: number) => {
    setScale(next);
    emit({ scale: next });
  };

  const handleDenseChange = (next: boolean) => {
    setDense(next);
    emit({ dense: next });
  };

  const handleFontChange = (next: FontFamily) => {
    setFont(next);
    emit({ font: next });
  };

  return (
    <section
      className="jx-panel"
      style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-5)' }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
        }}
      >
        <Text as="h2" className="jx-heading">
          Внешний вид
        </Text>
        <Badge variant="soft">{THEME_LABELS[theme]}</Badge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <Text as="label" className="jx-label">
          Тема
        </Text>
        <Segmented value={theme} onValueChange={handleThemeChange}>
          <SegmentedItem value="light">Светлая</SegmentedItem>
          <SegmentedItem value="dark">Тёмная</SegmentedItem>
          <SegmentedItem value="system">Системная</SegmentedItem>
        </Segmented>
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
          }}
        >
          <Text as="label" className="jx-label" htmlFor="appearance-scale">
            Масштаб интерфейса
          </Text>
          <Text as="span" className="jx-value">
            {scale}%
          </Text>
        </div>
        <Slider
          id="appearance-scale"
          min={80}
          max={140}
          step={5}
          value={scale}
          onValueChange={handleScaleChange}
          aria-valuetext={`${scale}%`}
        />
      </div>

      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
        }}
      >
        <Text as="label" className="jx-label" htmlFor="appearance-dense">
          Плотная вёрстка
        </Text>
        <Switch id="appearance-dense" checked={dense} onCheckedChange={handleDenseChange} />
      </div>

      <Divider />

      <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
        <Text as="h3" className="jx-subheading">
          Ещё
        </Text>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-2)' }}>
          <Text as="label" className="jx-label" htmlFor="appearance-font">
            Шрифт
          </Text>
          <Select id="appearance-font" value={font} onValueChange={handleFontChange}>
            <SelectItem value="system">{FONT_LABELS.system}</SelectItem>
            <SelectItem value="inter">{FONT_LABELS.inter}</SelectItem>
            <SelectItem value="mono">{FONT_LABELS.mono}</SelectItem>
          </Select>
        </div>
      </div>
    </section>
  );
}

